Future<dynamic> getOfflineNavaidData(String? navaidIdent) async {
  if (navaidIdent == null || navaidIdent.trim().isEmpty) return null;

  final navaids = NavaidData.getNavaidData(navaidIdent);
  if (navaids != null && navaids.isNotEmpty) {
    // بيرجع كل المحطات اللي بنفس الاسم
    return navaids.map((n) => n.toMap()).toList();
  }
  return null;
}

class NavaidModel {
  const NavaidModel({
    required this.name,
    required this.type,
    required this.freq,
    required this.lat,
    required this.lon,
    required this.elev,
    required this.country,
    required this.airport,
    required this.power,
  });

  final String name;
  final String type;
  final double freq;
  final double lat;
  final double lon;
  final double elev;
  final String country;
  final String airport;
  final String power;

  factory NavaidModel.fromMap(Map<String, dynamic> map) {
    return NavaidModel(
      name: map['name']?.toString() ?? '',
      type: map['type']?.toString() ?? '',
      freq: double.tryParse(map['freq']?.toString() ?? '0.0') ?? 0.0,
      lat: double.tryParse(map['lat']?.toString() ?? '0.0') ?? 0.0,
      lon: double.tryParse(map['lon']?.toString() ?? '0.0') ?? 0.0,
      elev: double.tryParse(map['elev']?.toString() ?? '0.0') ?? 0.0,
      country: map['country']?.toString() ?? '',
      airport: map['airport']?.toString() ?? '',
      power: map['power']?.toString() ?? 'UNKNOWN',
    );
  }

  Map<String, dynamic> toMap() => <String, dynamic>{
        'name': name,
        'type': type,
        'freq': freq,
        'lat': lat,
        'lon': lon,
        'elev': elev,
        'country': country,
        'airport': airport,
        'power': power,
      };
}

class NavaidData {
  NavaidData._();

  // الكاش بقى بيحفظ قائمة من المحطات
  static final Map<String, List<NavaidModel>> _cache =
      <String, List<NavaidModel>>{};

  static List<NavaidModel>? getNavaidData(String ident) {
    final String key = ident.trim().toUpperCase();
    if (key.isEmpty) return null;

    final List<Map<String, dynamic>>? dataList = _navaids[key];
    if (dataList == null || dataList.isEmpty) return null;

    return _cache.putIfAbsent(
      key,
      () => dataList.map((data) => NavaidModel.fromMap(data)).toList(),
    );
  }

  static bool containsNavaid(String ident) =>
      _navaids.containsKey(ident.trim().toUpperCase());

